WITH with_windows AS (SELECT *, LEAD(stock_qty) OVER w_recent AS next_stock_qty, LAG(stock_qty) OVER w_recent AS prev_stock_qty, LAG(cost) OVER w_recent AS prev_cost, LEAD(cost) OVER w_recent AS next_cost, ROW_NUMBER() OVER w_recent AS seq_no, AVG(cost) OVER (PARTITION BY brand) AS brand_avg_cost FROM products WINDOW w_recent AS (PARTITION BY supplier_id ORDER BY stock_qty, id)) SELECT id, category, cost, stock_qty, launch_date, prev_stock_qty, prev_cost, brand_avg_cost, CASE WHEN category RLIKE '^(Home|Books)$' THEN 'GROUP_A' WHEN category RLIKE '^(Electronics|Sports)$' THEN 'CORE' ELSE 'OTHER_ZONE' END AS category_zone FROM with_windows ORDER BY prev_stock_qty DESC NULLS LAST;
